OpeningRemakeV2.Bind();var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(OpeningRemakeV2.ScenePath);var root=scene.GetRootGameObjects().Single(r=>r.name=="Sanctuary").transform;
return root.GetComponentsInChildren<UnityEngine.Renderer>(true).Where(r=>r.name.StartsWith("Text")||r.name.StartsWith("Cylinder.10")).Select(r=>new {path=UnityEditor.AnimationUtility.CalculateTransformPath(r.transform,root),boundsCenter=r.bounds.center.ToString(),boundsSize=r.bounds.size.ToString(),localBounds=r.GetComponent<UnityEngine.MeshFilter>().sharedMesh.bounds.ToString(),vertices=r.GetComponent<UnityEngine.MeshFilter>().sharedMesh.vertexCount,materials=r.sharedMaterials.Select(m=>m.name).ToArray(),scale=r.transform.localScale.ToString(),rotation=r.transform.eulerAngles.ToString()}).ToArray();
